							increment(escape, prev);
						}
					}
				}

				inQuote = '\0';
			} else if (inQuote == '\0') {
				char prev = '\0';
				int j = i;
				while (prev <= ' ' && --j >= 0) {
					prev = characters[j];
				}
				if (j < 0 || !Character.isLetterOrDigit(prev)) {
					inQuote = ch;
				}
			}
			continue;
		}

