		if (sums.get(delimiterMin) == 0 && sums.get(delimiterMax) != 0) {
			delimiter = delimiterMin;
			break out;
		}

		for (char c : allowedDelimiters) {
			if (c == delimiterMin) {
				delimiter = delimiterMin;
				break out;
			} else if (c == delimiterMax) {
				delimiter = delimiterMax;
				break out;
			}
		}

		if (totals.get(delimiterMin) > totals.get(delimiterMax)) {
			delimiter = delimiterMin;
			break out;
		}
		delimiter = delimiterMax;
	} else {
		delimiter = delimiterMax;
	}

	char quote;
